int rds_atomic_op_process(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg)
{
    int ret = -EINVAL;

    if (cmsg->cmsg_len < CMSG_LEN(sizeof(struct rds_atomic_args)))
        return ret;

    struct rds_atomic_args *args = CMSG_DATA(cmsg);
    struct rds_atomic_op *op = &rm->atomic_op;

    if (op->active)
        return -EBUSY;

    switch (args->type) {
        case RDS_ATOMIC_ADD:
        case RDS_ATOMIC_FETCH_ADD:
        case RDS_ATOMIC_CMP_SET:
            op->type = args->type;
            break;
        default:
            return -EINVAL;
    }

    op->active = 1;
    op->arg_a = args->arg_a;
    op->arg_b = args->arg_b;

    op->sg = kmalloc(sizeof(struct scatterlist) * args->num_sges, GFP_KERNEL);
    if (!op->sg)
        return -ENOMEM;

    op->sg_count = args->num_sges;
    sg_init_table(op->sg, args->num_sges);
    for (int i = 0; i < args->num_sges; i++) {
        op->sg[i].page = args->sges[i].page;
        op->sg[i].offset = args->sges[i].offset;
        op->sg[i].length = args->sges[i].length;
    }

    if (op->type == RDS_ATOMIC_CMP_SET && args->notify) {
        op->notify = kzalloc(sizeof(struct rds_atomic_notifier), GFP_KERNEL);
        if (!op->notify) {
            kfree(op->sg);
            return -ENOMEM;
        }
    }

    memcpy(&op->remote_addr, &args->remote_addr, sizeof(op->remote_addr));
    op->key = args->key;

    return 0;
}

int rds_atomic_message_operation(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg)
{
    int ret = 0;
    struct rds_atomic_op_args *args;

    /* Validate control message length */
    if (cmsg->cmsg_len != sizeof(*args)) {
        return -EINVAL;
    }

    args = CMSG_DATA(cmsg);

    /* Check if an atomic operation is already active */
    if (rs->atomic_op_active) {
        return -EBUSY;
    }

    /* Set the operation type and parameters based on message type */
    switch (args->op_type) {
        case RDS_ATOMIC_OP_WRITE:
            rm->op_type = RDS_ATOMIC_OP_WRITE;
            break;
        case RDS_ATOMIC_OP_READ:
            rm->op_type = RDS_ATOMIC_OP_READ;
            break;
        default:
            return -EINVAL;
    }

    /* Allocate memory for scatter-gather list */
    rm->sg = kcalloc(args->sg_count, sizeof(*rm->sg), GFP_KERNEL);
    if (!rm->sg) {
        return -ENOMEM;
    }

    rm->sg_count = args->sg_count;

    /* Verify local address alignment */
    if (args->local_addr.align != RDS_ADDR_ALIGNMENT) {
        kfree(rm->sg);
        return -EALIGN;
    }

    /* Allocate notifier structure if notifications are required */
    if (args->notify) {
        rm->notifier = kzalloc(sizeof(*rm->notifier), GFP_KERNEL);
        if (!rm->notifier) {
            kfree(rm->sg);
            return -ENOMEM;
        }
    }

    /* Set the remote address and key */
    memcpy(&rm->remote_addr, &args->remote_addr, sizeof(args->remote_addr));
    rm->key = args->key;

    rs->atomic_op_active = 1;

    return ret;
}

int rds_atomic_message_operation(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg)
{
    int err = 0;
    struct rds_atomic_op_args *args;
    struct rds_atomic_operation *op;

    if (cmsg->cmsg_len != CMSG_LEN(sizeof(*args)))
        return -EINVAL;

    if (rs->atomic_op_active)
        return -EBUSY;

    args = CMSG_DATA(cmsg);
    if (args->version != RDS_ATOMIC_OP_CURRENT_VERSION)
        return -EINVAL;

    op = kzalloc(sizeof(*op), GFP_KERNEL);
    if (!op)
        return -ENOMEM;

    switch (args->type) {
    case RDS_ATOMIC_ADD:
        op->type = RDS_ATOMIC_ADD;
        break;
    case RDS_ATOMIC_SUB:
        op->type = RDS_ATOMIC_SUB;
        break;
    default:
        err = -EINVAL;
        goto out_free;
    }

    op->sg = kmalloc_array(args->num_sg, sizeof(*op->sg), GFP_KERNEL);
    if (!op->sg) {
        err = -ENOMEM;
        goto out_free;
    }

    if (args->num_sg > 0 && !IS_ALIGNED((unsigned long)args->sg[0].page, RDS_ATOMIC_ALIGNMENT)) {
        err = -EINVAL;
        goto out_free_sg;
    }

    if (args->notify) {
        op->notifier = kmalloc(sizeof(*op->notifier), GFP_KERNEL);
        if (!op->notifier) {
            err = -ENOMEM;
            goto out_free_sg;
        }
        init_waitqueue_head(&op->notifier->wait);
        op->notifier->flags = args->notify_flags;
    }

    op->remote_addr = args->remote_addr;
    op->key = args->key;

    rm->atomic_op = op;
    rs->atomic_op_active = true;

    return 0;

out_free_sg:
    kfree(op->sg);
out_free:
    kfree(op);
    return err;
}

int rds_atomic_op_process(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg)
{
    struct rds_atomic_args *args;
    int ret = -EINVAL;

    if (cmsg->cmsg_len != CMSG_LEN(sizeof(*args)))
        return -EINVAL;

    if (rm->atomic_op)
        return -EBUSY;

    args = CMSG_DATA(cmsg);
    switch (args->type) {
    case RDS_ATOMIC_CMPXCHG:
        rm->atomic_op_type = RDS_ATOMIC_CMPXCHG;
        break;
    case RDS_ATOMIC_FETCHADD:
        rm->atomic_op_type = RDS_ATOMIC_FETCHADD;
        break;
    default:
        return -EINVAL;
    }

    rm->atomic_op = kzalloc(sizeof(*args), GFP_KERNEL);
    if (!rm->atomic_op)
        return -ENOMEM;

    memcpy(rm->atomic_op, args, sizeof(*args));

    if (args->notify) {
        rm->atomic_notifier = kmalloc(sizeof(*rm->atomic_notifier), GFP_KERNEL);
        if (!rm->atomic_notifier) {
            kfree(rm->atomic_op);
            return -ENOMEM;
        }
    }

    memcpy(&rm->atomic_op->remote_addr, &args->remote_addr, sizeof(args->remote_addr));
    rm->atomic_op->key = args->key;

    return 0;
}

int rds_atomic_op_process(struct rds_sock *rs, struct rds_message *rm, struct cmsghdr *cmsg)
{
    int ret = -EINVAL;
    struct rds_atomic_op_args *args;
    struct rds_op_sg *sg;
    size_t cmsg_len = cmsg->cmsg_len - sizeof(struct cmsghdr);

    /* Validate control message length */
    if (cmsg_len < sizeof(*args))
        return ret;

    args = (struct rds_atomic_op_args *)CMSG_DATA(cmsg);
    if (rs->atomic_op_active)
        return -EBUSY;

    rm->op_type = args->op_type;
    rm->op_size = args->op_size;

    /* Allocate memory for scatter-gather list */
    sg = kmalloc(sizeof(*sg) * args->num_sg, GFP_KERNEL);
    if (!sg)
        return -ENOMEM;

    rm->sg = sg;
    rm->num_sg = args->num_sg;

    if (args->notify) {
        struct rds_notifier *notifier = kmalloc(sizeof(*notifier), GFP_KERNEL);
        if (!notifier) {
            kfree(sg);
            return -ENOMEM;
        }
        rm->notifier = notifier;
    }

    if (!is_aligned((unsigned long)args->addr, RDS_ALIGNMENT)) {
        ret = -EFAULT;
        goto out;
    }

    rm->remote_addr = args->addr;
    rm->key = args->key;
    rs->atomic_op_active = 1;
    return 0;

out:
    kfree(rm->sg);
    if (rm->notifier)
        kfree(rm->notifier);
    return ret;
}
